def oct13(x):
    n=1<<14; sp=np.zeros(n//2+1); c=0
    for i in range(0,len(x)-n,n//2):
        sp+=np.abs(np.fft.rfft(x[i:i+n]*np.hanning(n)))**2; c+=1
