import numpy as np, wave
w=wave.open('build/final.wav','rb'); sr=44100
d=np.frombuffer(w.readframes(w.getnframes()),dtype='<i2').reshape(-1,2).astype(float)/32768
m=d.mean(axis=1)
print('peak',round(float(np.abs(d).max()),3),'rms',round(float(np.sqrt((d**2).mean())),4))
def oct13(x):
    n=1<<14; sp=np.zeros(n//2+1); c=0
    for i in range(0,len(x)-n,n//2):
        sp+=np.abs(np.fft.rfft(x[i:i+n]*np.hanning(n)))**2; c+=1
    sp/=max(c,1); f=np.fft.rfftfreq(n,1/sr); fc=62.5; rows=[]
    while fc<18000:
        lo,hi=fc/2**(1/6),fc*2**(1/6); mk=(f>=lo)&(f<hi)
        if mk.sum(): rows.append((fc,10*np.log10(sp[mk].sum()/(hi-lo)+1e-20)))
        fc*=2**(1/3)
    ref=max(r[1] for r in rows)
    return ' '.join(f'{int(fc)}:{v-ref:.0f}' for fc,v in rows)
print('whole  ',oct13(m))
print('chorusB',oct13(m[int(38.4*sr):int(44.8*sr)]))
