{"command": "cd /workspace && python3 - <<'EOF'
import sys; sys.path.insert(0,'/workspace')
from build import P, PROG_A, PROG_B, PCN
from song import NCH
PROGS={0:'A',1:'A',2:'A',3:'A',4:'A',5:'A',6:'B',7:'B',8:'A',9:'A',10:'A',11:'A',12:'B',13:'B',14:'A'}
SC={9,11,0,2,4,5,7}
NAMES=['C','C#','D','D#','E','F','F#','G','G#','A','A#','B']
mel_ch={4,5,6,7,8,9,10,11,12}
bad=[]
for pi in range(15):
    prog = PROG_A if PROGS[pi]=='A' else PROG_B
    for (r,c),d in sorted(P[pi].c.items()):
        n=d.get('note')
        if not n or n==97 or c not in mel_ch: continue
        root,q = prog[(r//16)%len(prog)]
        pcs={(PCN[root]+i)%12 for i in ([0,3,7] if q=='min' else [0,4,7])}
        pc=(n-1)%12
        ok_scale = pc in SC or (q=='maj' and root=='E' and pc==8)
        if not ok_scale:
            bad.append((pi,r,c,NAMES[pc],root+q))
print('non-scale notes:',len(bad))
for x in bad[:30]: print('  ',x)
# count chord-tone ratio for lead channels
tot=ok=0
for pi in range(15):
    prog = PROG_A if PROGS[pi]=='A' else PROG_B
    for (r,c),d in sorted(P[pi].c.items()):
        n=d.get('note')
        if not n or n==97 or c not in (9,10,12): continue
        root,q = prog[(r//16)%len(prog)]
        pcs={(PCN[root]+i)%12 for i in ([0,3,7] if q=='min' else [0,4,7])}
        tot+=1; ok+= ((n-1)%12 in pcs)
print(f'lead chord-tone ratio {ok}/{tot} = {ok/tot:.2f}')
EOF"}

